from pathlib import Path
import base64
import sys

LAYOUT = Path("app/(portal)/layout.tsx")
PROVIDER = Path("components/notifications/portal-notification-counts-provider.tsx")
REGISTRATION = Path("components/admin/registration-application-badge.tsx")
ORDER = Path("components/admin/order-submission-badge.tsx")
SUBMITTED = Path("components/admin/submitted-character-badge.tsx")
TICKET = Path("components/support/ticket-notification-badge.tsx")
SANCTION = Path("components/sanctions/sanction-notification-badge.tsx")
PLAYER_SANCTIONS = Path("components/sanctions/player-sanctions-sidebar-link.tsx")

TARGETS = [LAYOUT, REGISTRATION, ORDER, SUBMITTED, TICKET, SANCTION, PLAYER_SANCTIONS]

def fail(message):
    print(f"ERROR: {message}")
    print("No files were changed.")
    sys.exit(1)

for path in TARGETS:
    if not path.exists():
        fail(f"{path} not found. Run this script from the repository root.")

if PROVIDER.exists():
    fail(f"{PROVIDER} already exists. This patch expects commit 94179cb before centralisation.")

expected = {
    REGISTRATION: "20_000",
    ORDER: "window.setInterval(() => void refresh(), 20000)",
    SUBMITTED: "}, 20_000);",
    TICKET: "window.setInterval(()=>void refresh(),20000)",
    SANCTION: "setInterval(()=>void r(),20000)",
    PLAYER_SANCTIONS: "setInterval(()=>void r(),20000)",
}

for path, marker in expected.items():
    if marker not in path.read_text(encoding="utf-8"):
        fail(f"{path} is not in the expected pre-centralisation state.")

layout = LAYOUT.read_text(encoding="utf-8")

def replace_once(text, old, new, label):
    if text.count(old) != 1:
        fail(f"{label} anchor not found exactly once.")
    return text.replace(old, new, 1)

layout = replace_once(
    layout,
    'import { PortalPresenceHeartbeat } from "@/components/portal/portal-presence-heartbeat";',
    'import { PortalNotificationCountsProvider } from "@/components/notifications/portal-notification-counts-provider";\nimport { PortalPresenceHeartbeat } from "@/components/portal/portal-presence-heartbeat";',
    "provider import",
)

layout = replace_once(
    layout,
    'import { getPortalContext } from "@/lib/portal/get-portal-context";',
    'import { getStaffSession } from "@/lib/auth/require-staff";\nimport { getPortalContext } from "@/lib/portal/get-portal-context";',
    "staff import",
)

old_promise = '''  const [
    context,
    worldState,
    initialTidings,
    unreadForumCount,
  ] = await Promise.all([
    getPortalContext(),
    getWorldState(),
    getActiveTidings(),
    getUnreadForumCount(),
  ]);'''

new_promise = '''  const [
    context,
    worldState,
    initialTidings,
    unreadForumCount,
    staffSession,
  ] = await Promise.all([
    getPortalContext(),
    getWorldState(),
    getActiveTidings(),
    getUnreadForumCount(),
    getStaffSession(),
  ]);'''

layout = replace_once(
    layout,
    old_promise,
    new_promise,
    "portal Promise.all",
)

layout = replace_once(
    layout,
    '''        <PortalAudioProvider>
        <PortalMessageSoundListener''',
    '''        <PortalAudioProvider>
        <PortalNotificationCountsProvider
          staffRole={staffSession?.role ?? null}
        >
        <PortalMessageSoundListener''',
    "provider opening",
)

layout = replace_once(
    layout,
    '''        </PortalAudioProvider>
      </PortalSkinProvider>''',
    '''        </PortalNotificationCountsProvider>
        </PortalAudioProvider>
      </PortalSkinProvider>''',
    "provider closing",
)

def decode(value):
    return base64.b64decode(value).decode("utf-8")

# All validation finished before any write.
LAYOUT.write_text(layout, encoding="utf-8")
PROVIDER.parent.mkdir(parents=True, exist_ok=True)
PROVIDER.write_text(decode(''), encoding="utf-8")
REGISTRATION.write_text(decode(''), encoding="utf-8")
ORDER.write_text(decode(''), encoding="utf-8")
SUBMITTED.write_text(decode(''), encoding="utf-8")
TICKET.write_text(decode(''), encoding="utf-8")
SANCTION.write_text(decode(''), encoding="utf-8")
PLAYER_SANCTIONS.write_text(decode(''), encoding="utf-8")

print("Centralised slow badge counts.")
print("")
print("Modified:")
for path in TARGETS:
    print(f" - {path}")
print("Created:")
print(f" - {PROVIDER}")
print("")
print("One shared 20-second timer now owns these counts.")
print("Cog/nav/sidebar copies only read shared state.")
print("Ticket and sanctions change events still refresh immediately.")
print("Submitted-character realtime refresh is preserved with one shared channel.")
print("Focus refresh is preserved with one shared listener.")
print("Same-category overlapping requests are deduplicated.")
print("Private Messages, Forum, Instant Chat, presence, world tick and portal-session checks were untouched.")
print("No backup files were created.")
